"""assessment_sg — assessment-item generation (GENERATED by default).

    resolve -> [item_source?]
      generated -> plan_coverage -> retrieve_batch -> generate -> validate
      bank      -> query_bank ─────────────────────────────────→ validate
      hybrid    -> query_bank -> plan_coverage -> retrieve_batch -> generate -> validate

Private state (``AssessmentState``); the parent adapter hands it concrete namespaces /
language / type_mix. GENERATED grounds every item in a retrieved chunk and stamps it
with that chunk's ``topic_id`` + ``lecture_id`` (invariant 12); ``resolve_topics``
runs first (invariant 8). BANK/HYBRID are built but config-off. ``validate`` enforces
``type_mix`` deterministically — no second LLM pass.
"""

from __future__ import annotations

import logging
from typing import Any, TypedDict

from langchain_core.messages import HumanMessage

from shared.language import content_directive
from shared.structured import align_by_id, call_structured, schema_hint

from ... import retrieval
from ...models import QUESTION_TYPES, AssessmentItem, AssessmentOption, DraftBatch
from ...prompts import ASSESSMENT_BATCH_PROMPT
from ...retrieval import DEFAULT_MIN_SCORE
from ...tools import get_mastery, get_question_bank, resolve_topics

logger = logging.getLogger(__name__)

# status -> priority for adaptive coverage (lower = more practice needed).
_WEAKNESS_RANK = {"weak": 0, "unknown": 1, "developing": 2, "strong": 3}


class AssessmentState(TypedDict, total=False):
    # inputs
    query: str
    subject_id: str | None
    lecture_ids: list[str] | None  # optional lecture scope; None -> whole subject
    topic_ids: list[str]
    namespaces: list[str]
    # language is the SUBJECT's language when known (set by the assessment adapter),
    # else the turn language.
    language: str
    instructions: str                # subject-specific prompt addendum (e.g. math), or ""
    grade: str | None
    user_id: str | None
    item_source: str                 # generated | bank | hybrid
    type_mix: dict[str, int]
    difficulty: str
    k_per_topic: int
    min_score: float                 # retrieval floor — off-syllabus -> decline
    adaptive: bool
    # produced
    coverage: list[dict[str, Any]]   # [{topic_id, type}]
    chunks_by_topic: dict[str, list]
    items: list[AssessmentItem]      # typed, DB-shaped; dumped to dicts in `assessment`
    degraded: bool                   # true when the generation LLM call failed
    assessment: dict[str, Any]


# --- pure helpers (unit-tested directly) ------------------------------------

def _flatten_type_mix(type_mix: dict[str, int]) -> list[str]:
    """Ordered list of per-item types, e.g. {mcq:2, essay:1} -> [mcq, mcq, essay]."""
    out: list[str] = []
    for t in QUESTION_TYPES:
        out.extend([t] * max(0, int(type_mix.get(t, 0))))
    return out


def _order_topics_by_weakness(
    topic_ids: list[str], mastery_rows: list[dict]
) -> list[str]:
    """Weakest-first ordering so adaptive coverage practises shaky topics more.
    Topics with no mastery row count as ``unknown``."""
    status = {r.get("topic_id"): r.get("status") for r in mastery_rows}
    return sorted(
        topic_ids,
        key=lambda t: _WEAKNESS_RANK.get(status.get(t, "unknown"), 1),
    )


_DIFF_ROTATION = ("easy", "medium", "hard")


def _spread_difficulty(n: int, difficulty: str) -> list[str]:
    """Per-item difficulty. A concrete level is used for every item; ``mixed`` (or any
    unknown value) rotates easy -> medium -> hard so one assessment spans levels."""
    if difficulty in _DIFF_ROTATION:
        return [difficulty] * n
    return [_DIFF_ROTATION[i % len(_DIFF_ROTATION)] for i in range(n)]


# TODO (2E / enhancement): richer coverage control. Today this is a flat weakest-first
# round-robin (topic = types[i] -> topics[i % n]). Consider: (a) strong weak-point RATIOS
# (spend MORE questions on weak topics, not just order them first); (b) per-topic question
# counts as an explicit input; (c) a type x topic coverage matrix (each type spans the topics).
def _assign_slots(
    types: list[str], ordered_topics: list[str], difficulties: list[str]
) -> list[dict]:
    """Zip each item-type to a topic (cycling weakest-first) and a difficulty. No
    topics -> topic None (generate stamps from the retrieved chunk)."""
    topics = ordered_topics or [None]
    return [
        {"topic_id": topics[i % len(topics)], "type": t, "difficulty": difficulties[i]}
        for i, t in enumerate(types)
    ]


def _build_item(base: dict, raw: dict) -> AssessmentItem | None:
    """Build a typed, DB-shaped item from a slot ``base`` and a generated question.

    MCQ correctness comes from ``correct_indices`` — positions, not text. Matching
    the answer string against the option text produced questions with no correct
    option whenever the model answered "A" instead of repeating the sentence, and
    those still passed the well-formed check.
    """
    if not raw.get("question"):
        return None
    answer = raw.get("answer")
    raw_opts = raw.get("options") or []
    options = None
    if raw_opts:
        indices = raw.get("correct_indices")
        if indices:
            correct_positions = {int(i) for i in indices}
            options = [AssessmentOption(text=str(o), is_correct=i in correct_positions)
                       for i, o in enumerate(raw_opts)]
            answer = answer or [str(raw_opts[i]) for i in sorted(correct_positions)
                                if 0 <= i < len(raw_opts)]
        else:
            correct = set(answer) if isinstance(answer, list) else ({answer} if answer else set())
            options = [AssessmentOption(text=str(o), is_correct=str(o) in correct)
                       for o in raw_opts]
    try:
        return AssessmentItem(
            type=base["type"],
            question=raw["question"],
            topic_id=base.get("topic_id"),      # required -> ValidationError if missing
            lecture_id=base.get("lecture_id"),  # required -> ValidationError if missing
            answer=answer,
            options=options,
            explanation=raw.get("explanation"),
            difficulty=base.get("difficulty", "medium"),
        )
    except Exception:
        return None


def _well_formed(item: AssessmentItem) -> bool:
    """topic_id/lecture_id/question are guaranteed by construction (invariant 12);
    this adds the type-specific rule: an MCQ needs >=2 options, everything else an
    answer."""
    if item.type == "mcq":
        return (bool(item.options) and len(item.options) >= 2
                and any(option.is_correct for option in item.options))
    return bool(item.answer)


def _enforce_type_mix(
    items: list[AssessmentItem], type_mix: dict[str, int]
) -> list[AssessmentItem]:
    """Keep up to the target count of well-formed items per type; drop the rest.
    Deterministic — preserves order, no model call."""
    kept: list[AssessmentItem] = []
    per_type: dict[str, int] = {}
    for it in items:
        if it.type not in QUESTION_TYPES or not _well_formed(it):
            continue
        target = int(type_mix.get(it.type, 0))
        if per_type.get(it.type, 0) >= target:
            continue
        per_type[it.type] = per_type.get(it.type, 0) + 1
        kept.append(it)
    return kept


# --- nodes ------------------------------------------------------------------

def _resolve(state: AssessmentState) -> dict:
    if state.get("topic_ids"):
        return {}
    hits = resolve_topics(state.get("query") or "", state.get("subject_id"),
                          lecture_ids=state.get("lecture_ids") or None)
    return {"topic_ids": [h.topic_id for h in hits]}


def _plan_coverage(state: AssessmentState) -> dict:
    types = _flatten_type_mix(state.get("type_mix") or {})
    # Dedupe topics so the same concept isn't slotted twice.
    topic_ids = list(dict.fromkeys(state.get("topic_ids") or []))
    ordered = topic_ids
    if topic_ids and state.get("adaptive") and state.get("user_id"):
        try:
            rows = get_mastery(state["user_id"], topic_ids)
            ordered = _order_topics_by_weakness(topic_ids, rows)
        except Exception:
            logger.warning("get_mastery failed; unweighted coverage", exc_info=True)
    difficulties = _spread_difficulty(len(types), state.get("difficulty", "mixed"))
    coverage = _assign_slots(types, ordered, difficulties)
    logger.info("plan_coverage", extra={
        "slots": len(coverage), "topics": len(topic_ids),
        "difficulties": difficulties})
    return {"coverage": coverage}


def _retrieve_batch(state: AssessmentState) -> dict:
    namespaces = state.get("namespaces") or ["syllabus"]
    k = state.get("k_per_topic", 4)
    topics = {slot["topic_id"] for slot in state.get("coverage", [])}
    by_topic: dict[str, list] = {}
    for topic in topics:
        chunks = retrieval.retrieve(
            state.get("query") or "",
            namespaces,
            subject_id=state.get("subject_id"),
            topic_ids=[topic] if topic else None,
            lecture_ids=state.get("lecture_ids") or None,
            k=k,
            min_score=state.get("min_score", DEFAULT_MIN_SCORE),
        )
        by_topic[topic or ""] = chunks
    logger.info("retrieve_batch", extra={
        "topics": len(by_topic), "chunks": sum(len(v) for v in by_topic.values())})
    return {"chunks_by_topic": by_topic}


def _next_chunk(chunks: list, key: str, cursors: dict, used: set):
    """Pick a chunk for a slot, preferring one not already used this assessment so items
    are distinct; only reuse when every chunk for the slot is exhausted."""
    if not chunks:
        return None
    n = len(chunks)
    start = cursors.get(key, 0)
    for offset in range(n):
        c = chunks[(start + offset) % n]
        cid = getattr(c, "chunk_id", None)
        if cid not in used:
            cursors[key] = start + offset + 1
            if cid is not None:
                used.add(cid)
            return c
    cursors[key] = start + 1          # all used -> reuse
    return chunks[start % n]


def _bind_chunks(state: AssessmentState) -> list[tuple[dict, object]]:
    """Give each coverage slot a distinct chunk (dropping slots with no chunk), so a
    assessment spans different passages rather than re-asking the same one."""
    by_topic = state.get("chunks_by_topic", {})
    cursors: dict[str, int] = {}
    used: set = set()
    bound: list[tuple[dict, object]] = []
    for slot in state.get("coverage", []):
        key = slot.get("topic_id") or ""
        chunks = by_topic.get(key) or by_topic.get("") or []
        chunk = _next_chunk(chunks, key, cursors, used)
        if chunk is not None:
            bound.append((slot, chunk))
    return bound


def _slot_base(slot: dict, chunk) -> dict:
    """The invariant-12 spine of an item: type, the SLOT's topic (fallback chunk),
    lecture_id, and difficulty."""
    return {
        "type": slot["type"],
        "topic_id": _stamp_topic(chunk, slot.get("topic_id")),
        "lecture_id": getattr(chunk, "lecture_id", None),
        "difficulty": slot.get("difficulty", "medium"),
        "heading_path": getattr(chunk, "heading_path", None),
    }


def _stub_items(bound: list[tuple[dict, object]]) -> list[AssessmentItem]:
    """Deterministic grounded stub, one typed item per slot (no LLM / no key)."""
    return [it for s, c in bound
            if (it := _build_item(_slot_base(s, c), _stub_item(s["type"], c)))]


# TODO (deferred): per-item figures — a math/diagram question could emit its own figure spec
# (carrying the item's id) via the visual_specs + item_id channel, rendered by visual_sg.
def _build_generate(llm, config):
    def _generate(state: AssessmentState) -> dict:
        bound = _bind_chunks(state)
        if not bound:
            logger.info("generate", extra={"items": 0})
            return {"items": []}
        if llm is None:                          # dev/test: no key -> deterministic stub
            items = _stub_items(bound)
        else:
            try:
                items = _batch_generate(llm, bound, state, config)
            except Exception:
                # Runtime failure: degrade rather than emit placeholder questions.
                logger.error("assessment generation failed; degrading", exc_info=True)
                return {"items": [], "degraded": True}
        logger.info("generate", extra={"items": len(items), "calls": 0 if llm is None else 1})
        return {"items": items}

    return _generate


def _batch_generate(
    llm, bound: list[tuple[dict, object]], state: AssessmentState, config=None,
) -> list[AssessmentItem]:
    """Generate the whole assessment in ONE LLM call (much faster than per-item, and the
    model sees all items so it avoids duplicates). The batch is a validated ``DraftBatch``
    via structured output (JSON-parse fallback); items map back to slots by position, each
    validated into a typed ``AssessmentItem`` (invalid dropped). A real call failure
    propagates so the generate node degrades (no placeholder items)."""
    blocks = [
        f"Block id={_block_id(i)}: type={slot['type']}, "
        f"difficulty={slot.get('difficulty', 'medium')}\n"
        f"Context:\n{getattr(chunk, 'text', '')}"
        for i, (slot, chunk) in enumerate(bound, 1)
    ]
    prompt_text = ASSESSMENT_BATCH_PROMPT.format(
        schema=schema_hint(DraftBatch),
        language=content_directive(state.get("language", "en")),
        instructions=state.get("instructions", ""),
        query=state.get("query", ""),
        n=len(bound),
        items_block="\n\n".join(blocks),
    )
    expected = [_block_id(i) for i in range(1, len(bound) + 1)]
    batch = call_structured(
        DraftBatch,
        [HumanMessage(content=prompt_text)],
        task="assessment", config=config, llm=llm, label="assessment",
        validate=lambda b: align_by_id(expected, b.items, what="question"),
    )
    drafts = align_by_id(expected, batch.items, what="question")

    items: list[AssessmentItem] = []
    for (slot, chunk), draft in zip(bound, drafts):
        item = _build_item(_slot_base(slot, chunk), draft.model_dump())
        if item is not None:
            items.append(item)
    return items


def _block_id(index: int) -> str:
    """The id a block is labelled with, and its question must come back carrying."""
    return f"b{index}"


def _stamp_topic(chunk, slot_topic: str | None = None) -> str | None:
    """Prefer the slot's covered topic (so items spread across the matched topics);
    fall back to the chunk's own topic (invariant 12)."""
    if slot_topic:
        return slot_topic
    chunk_topics = getattr(chunk, "topic_ids", None) or []
    return chunk_topics[0] if chunk_topics else None


def _stub_item(qtype: str, chunk) -> dict:
    head = getattr(chunk, "heading_path", None) or getattr(chunk, "lecture_id", "")
    q = f"[{qtype} pending chat model] Question grounded in: {head}"
    if qtype == "mcq":
        return {"question": q, "options": ["A", "B", "C", "D"], "answer": "A",
                "explanation": "grounded stub"}
    if qtype == "true_false":
        return {"question": q, "answer": "true", "explanation": "grounded stub"}
    return {"question": q, "answer": "(model answer pending)",
            "explanation": "grounded stub"}


def _query_bank(state: AssessmentState) -> dict:
    """BANK/HYBRID source — existing items from the backend (config-off by default),
    normalised into the same typed ``AssessmentItem`` shape as GENERATED."""
    rows = get_question_bank(
        state.get("subject_id") or "",
        topic_ids=state.get("topic_ids") or None,
        count=sum((state.get("type_mix") or {}).values()),
    )
    built = [
        _build_item(
            {"type": q.get("question_type"),
             "topic_id": (q.get("topic_ids") or [None])[0],
             "lecture_id": q.get("lecture_id"),
             "difficulty": q.get("difficulty", "medium")},
            {"question": q.get("question_text"), "options": q.get("options"),
             "answer": q.get("correct_answer_text"), "explanation": q.get("explanation")},
        )
        for q in rows
    ]
    return {"items": state.get("items", []) + [it for it in built if it is not None]}


def _validate(state: AssessmentState) -> dict:
    type_mix = state.get("type_mix") or {}
    kept = _enforce_type_mix(state.get("items", []), type_mix)
    actual: dict[str, int] = {}
    for it in kept:
        actual[it.type] = actual.get(it.type, 0) + 1
    assessment = {
        # subject_id stamps the whole assessment -> quizzes.subject_id on save; each item
        # carries its own topic_id + lecture_id (invariant 12). Items are DB-shaped dicts.
        "subject_id": state.get("subject_id"),
        "items": [it.model_dump() for it in kept],
        "count": len(kept),
        "type_mix": actual,
        "requested_type_mix": type_mix,
        "source": state.get("item_source", "generated"),
        "language": state.get("language", "en"),
        "complete": all(actual.get(t, 0) >= int(type_mix.get(t, 0)) for t in QUESTION_TYPES),
        "degraded": state.get("degraded", False),   # LLM failure -> friendly note in compose
    }
    logger.info("validate", extra={"kept": len(kept), "complete": assessment["complete"]})
    return {"assessment": assessment, "items": kept}


# --- routing + build --------------------------------------------------------

def _after_resolve(state: AssessmentState) -> str:
    # bank/hybrid start from existing backend items; generated goes straight to coverage planning.
    return "query_bank" if state.get("item_source") in ("bank", "hybrid") else "plan_coverage"


def _after_bank(state: AssessmentState) -> str:
    # hybrid tops the bank items up with generated ones; bank-only skips generation.
    return "plan_coverage" if state.get("item_source") == "hybrid" else "validate"


def build_assessment_sg(*, config, llm=None):
    from langgraph.graph import END, START, StateGraph

    graph = StateGraph(AssessmentState)
    graph.add_node("resolve", _resolve)
    graph.add_node("query_bank", _query_bank)
    graph.add_node("plan_coverage", _plan_coverage)
    graph.add_node("retrieve_batch", _retrieve_batch)
    graph.add_node("generate", _build_generate(llm, config))
    graph.add_node("validate", _validate)

    # Three source paths converge on `validate`: generated (resolve->plan->retrieve->generate),
    # bank (resolve->query_bank), hybrid (bank items + a generated top-up).
    graph.add_edge(START, "resolve")
    graph.add_conditional_edges("resolve", _after_resolve,
                                ["query_bank", "plan_coverage"])
    graph.add_conditional_edges("query_bank", _after_bank,
                                ["plan_coverage", "validate"])
    graph.add_edge("plan_coverage", "retrieve_batch")
    graph.add_edge("retrieve_batch", "generate")
    graph.add_edge("generate", "validate")
    graph.add_edge("validate", END)
    return graph.compile()
